import type { WisdomArchetype } from "./types";

export const WISDOM_BHAGAVAD_GITA: WisdomArchetype[] = [
  { concept: "Karma Yoga — Action Without Attachment to Fruits", tradition: "Bhagavad Gita", source: "Bhagavad Gita 2.47", explanation: "Krishna's central teaching to Arjuna: you have a right to action alone, never to its fruits. The work is yours; the result belongs to causes beyond you. Acting with full effort while releasing the outcome is the yoga of action.", application: "Before any significant task, commit completely to the doing and consciously release the result. Work with full attention, hold the outcome loosely.", questions: ["What am I gripping the result of?", "Can I do this work well even if no one notices?", "What changes when the fruit is not mine to claim?"], references: ["Bhagavad Gita 2.47", "Bhagavad Gita 3.19", "Bhagavad Gita 18.47"], excerpt: "karmaṇy evādhikāras te mā phaleṣu kadācana — You have a right to action, never to its fruits.", evidence: "traditional", dimensions: ["action", "thought"], paths: ["karma"], domains: ["work", "growth"], tags: ["gita", "karma_yoga", "action", "fruits", "detachment"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Eternal Self (Atman)", tradition: "Bhagavad Gita", source: "Bhagavad Gita 2.20", explanation: "The Self is never born and never dies; it is unborn, eternal, and primeval. It is not slain when the body is slain. The Gita's opening metaphysical teaching establishes the deathless witness beneath all change.", application: "In moments of loss or transition, distinguish the unchanging witness from the changing circumstances. What was aware of the loss was not lost.", questions: ["What in me was never born and cannot die?", "How does acting from the deathless change my relationship to failure?", "What remains when every role is set aside?"], references: ["Bhagavad Gita 2.20", "Bhagavad Gita 2.22", "Kathopanishad"], excerpt: "na jāyate mriyate vā kadācin — The Self is never born, nor does it ever die.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana", "raja"], domains: ["spirituality", "growth"], tags: ["gita", "atman", "eternal", "deathless", "witness"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Two Bodies — Garments of the Soul", tradition: "Bhagavad Gita", source: "Bhagavad Gita 2.22", explanation: "As a person casts off worn-out garments and takes new ones, the Self casts off worn-out bodies and accepts new ones. The body is clothing; the wearer is untouched by its changes.", application: "When the body ages, fails, or changes, remember the metaphor of garments. Care for the body without identifying as it.", questions: ["If the body is a garment, who is wearing it?", "How does this metaphor change my relationship to aging?", "What do I cling to that is clothing, not self?"], references: ["Bhagavad Gita 2.22", "Bhagavad Gita 2.18"], excerpt: "vāsāṁsi jīrṇāni yathā vihāya — As one casts off worn-out garments and takes new ones.", evidence: "traditional", dimensions: ["spirit", "body"], paths: ["jnana"], domains: ["spirituality", "health"], tags: ["gita", "body", "garments", "rebirth", "metaphor"], difficulty: "beginner", minutes: 5 },
  { concept: "Anger, Delusion, and the Chain of Destruction", tradition: "Bhagavad Gita", source: "Bhagavad Gita 2.62-2.63", explanation: "Contemplating sense objects breeds attachment; attachment breeds desire; desire breeds anger; anger breeds delusion; delusion destroys memory; destroyed memory destroys intelligence; and one perishes. The Gita maps the precise chain from a glance to ruin.", application: "Catch the chain at its first link — the contemplation of the sense object — before attachment, desire, and anger assemble. The earliest link is the easiest to break.", questions: ["Where is my chain today — at which link?", "What sense object do I contemplate most dangerously?", "How do I interrupt the chain at link one?"], references: ["Bhagavad Gita 2.62-2.63", "Bhagavad Gita 3.36-3.43"], excerpt: "dhyāyato viṣayān puṁsaḥ saṅgas teṣūpajāyate — Contemplating sense objects, attachment arises.", evidence: "traditional", dimensions: ["thought", "emotion"], paths: ["raja", "jnana"], domains: ["growth", "relationships"], tags: ["gita", "anger", "chain", "attachment", "delusion"], difficulty: "beginner", minutes: 6 },
  { concept: "Skill in Action Is Yoga", tradition: "Bhagavad Gita", source: "Bhagavad Gita 2.50", explanation: "Yoga is skill in action — not withdrawal from the world, but the performance of action with such evenness that its quality becomes the practice itself. The workplace becomes the ashram.", application: "Treat the next task as yoga: full attention, even effort, no anxiety about outcome. Skill in action is measurable — it shows as calm competence under pressure.", questions: ["Where is my action currently unskillful — rushed, anxious, or resentful?", "What would 'skill in action' look like in my next meeting?", "How does releasing the fruit improve the work itself?"], references: ["Bhagavad Gita 2.50", "Bhagavad Gita 2.48"], excerpt: "yogaḥ karmasu kauśalam — Yoga is skill in action.", evidence: "traditional", dimensions: ["action", "thought"], paths: ["karma", "raja"], domains: ["work"], tags: ["gita", "skill", "action", "workplace", "evenness"], difficulty: "beginner", minutes: 5 },
  { concept: "Equanimity — Sthitaprajna", tradition: "Bhagavad Gita", source: "Bhagavad Gita 2.55-2.72", explanation: "The steadfast one (sthita-prajna) is described in detail: undisturbed in joy and sorrow, like the ocean unmoved by rivers of desire, free from attachment and aversion, with senses withdrawn like a tortoise's limbs. The Gita's portrait of the unshakable mind.", application: "Use the sthitaprajna description as a daily checklist: Was I disturbed by pleasure or pain today? Did my senses drag me, or did I withdraw them like the tortoise?", questions: ["Which of the sthitaprajna qualities did I express today?", "Where was I like the ocean, where like the storm?", "What would one more degree of equanimity change tomorrow?"], references: ["Bhagavad Gita 2.55-2.72", "Bhagavad Gita 5.20"], excerpt: "sthita-prajñasya kāṁṁsi... — Of the steadfast in wisdom, the senses are restrained.", evidence: "traditional", dimensions: ["emotion", "thought", "spirit"], paths: ["raja", "jnana"], domains: ["growth", "work"], tags: ["gita", "equanimity", "sthita_prajna", "ocean", "tortoise"], difficulty: "intermediate", minutes: 8 },
  { concept: "No Moment Is Wasted in Action", tradition: "Bhagavad Gita", source: "Bhagavad Gita 3.5", explanation: "Not for a single moment can anyone remain without action — even unwillingly, one is forced to act by the qualities of nature. The teaching: since action is compulsory, make it conscious.", application: "Stop trying to escape action; instead, make the unavoidable action chosen. The question is never whether to act but with what awareness.", questions: ["What am I doing unwillingly right now?", "How would I do it differently if I chose it?", "What is the smallest action I can make fully conscious today?"], references: ["Bhagavad Gita 3.5", "Bhagavad Gita 3.6"], excerpt: "na hi kaścit kṣaṇam api juṣyate — Not for a moment can anyone remain without action.", evidence: "traditional", dimensions: ["action", "thought"], paths: ["karma"], domains: ["work", "growth"], tags: ["gita", "action", "unavoidable", "conscious", "compulsory"], difficulty: "beginner", minutes: 5 },
  { concept: "Sacrifice as the Engine of the World", tradition: "Bhagavad Gita", source: "Bhagavad Gita 3.9-3.15", explanation: "Work done as sacrifice (yajna) sustains the world; the gods sustain you through sacrifice, and mutual sustenance is the wheel of life. Action offered rather than consumed dissolves karma.", application: "Before starting work, offer it: this task is done for the whole, not for my credit. The offering transforms the same action's inner chemistry.", questions: ["To whom is my work offered?", "What would change if today's work were a sacrifice rather than a transaction?", "Where am I consuming rather than offering?"], references: ["Bhagavad Gita 3.9-3.15", "Bhagavad Gita 9.27"], excerpt: "yajña-śiṣṭāśinaḥ santo mucyante sarva-kilbiṣaiḥ — Those who eat the remnants of sacrifice are freed from all sins.", evidence: "traditional", dimensions: ["action", "spirit"], paths: ["karma", "bhakti"], domains: ["work", "community"], tags: ["gita", "yajna", "sacrifice", "offering", "karma"], difficulty: "intermediate", minutes: 7 },
  { concept: "One's Own Dharma, Imperfect, Beats Another's Perfect", tradition: "Bhagavad Gita", source: "Bhagavad Gita 3.35, 18.47", explanation: "Better one's own dharma, though imperfect, than another's well performed. Better to die in one's own dharma; another's dharma brings fear. The Gita's radical teaching against comparison and imitation.", application: "When comparing your path to another's, recall: their dharma is not yours. The imperfect pursuit of your own nature beats the perfect imitation of theirs.", questions: ["Whose dharma am I secretly trying to live?", "What is imperfect in my own path that I keep abandoning?", "What would my own dharma look like this year?"], references: ["Bhagavad Gita 3.35", "Bhagavad Gita 18.47"], excerpt: "śreyān sva-dharmo viguṇaḥ para-dharmāt — Better one's own dharma, though imperfect.", evidence: "traditional", dimensions: ["action", "thought", "spirit"], paths: ["karma", "jnana"], domains: ["purpose", "growth"], tags: ["gita", "svadharma", "dharma", "comparison", "own_path"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Descent of the Divine — Avatar", tradition: "Bhagavad Gita", source: "Bhagavad Gita 4.7-4.8", explanation: "Whenever dharma declines and adharma rises, I manifest myself. For the protection of the good, the destruction of the wicked, and the establishment of dharma, I come into being, age after age. The Gita's doctrine of divine descent.", application: "The teaching applies personally: whenever your own dharma declines, the corrective 'descent' is available — a renewed commitment, a hard conversation, a changed habit. You are the agent of your own restoration.", questions: ["Where has my dharma declined?", "What would my 'descent' — my corrective action — look like?", "What am I waiting to be protected from, that I can protect myself from?"], references: ["Bhagavad Gita 4.7-4.8"], excerpt: "yadā yadā hi dharmasya glānir bhavati bhārata — Whenever dharma declines, I manifest.", evidence: "traditional", dimensions: ["spirit", "action"], paths: ["bhakti"], domains: ["purpose", "growth"], tags: ["gita", "avatar", "descent", "dharma", "manifestation"], difficulty: "intermediate", minutes: 6 },
  { concept: "Renunciation and Action Are Both Liberation", tradition: "Bhagavad Gita", source: "Bhagavad Gita 5.2-5.3", explanation: "The foolish see renunciation and action as different; the wise see them as one. True renunciation is not abandoning action but abandoning attachment to its fruits — the same teaching as karma yoga, seen from another angle.", application: "Stop choosing between 'doing more' and 'withdrawing more.' The real question is always: how attached am I to the result?", questions: ["Am I using renunciation to avoid action, or action to avoid renunciation?", "Where is my attachment to results disguised as duty?", "What would unattached action look like today?"], references: ["Bhagavad Gita 5.2-5.3", "Bhagavad Gita 18.49"], excerpt: "sannyāsaḥ karmaṇāṁ... — Renunciation and action both lead to liberation.", evidence: "traditional", dimensions: ["thought", "action"], paths: ["karma", "jnana"], domains: ["growth", "work"], tags: ["gita", "renunciation", "sannyasa", "action", "liberation"], difficulty: "intermediate", minutes: 6 },
  { concept: "Lift Yourself by Yourself", tradition: "Bhagavad Gita", source: "Bhagavad Gita 6.5", explanation: "Lift yourself by yourself; do not degrade yourself. The Self is both friend and enemy — for the self-controlled, the Self is a friend; for the undisciplined, it is an enemy. No one else can do this lifting.", application: "Stop waiting for external rescue. The next upward step is yours to take, today, without permission. The same inner instrument that dragged you down can lift you up.", questions: ["What am I waiting to be rescued from, and by whom?", "How has my own mind been my enemy this week?", "What is the one self-lifting step available today?"], references: ["Bhagavad Gita 6.5", "Bhagavad Gita 6.6"], excerpt: "uddhared ātmanātmanāṁ — Lift yourself by yourself.", evidence: "traditional", dimensions: ["action", "thought", "spirit"], paths: ["raja", "karma"], domains: ["growth", "self_care"], tags: ["gita", "self_effort", "uplift", "friend", "enemy"], difficulty: "beginner", minutes: 5 },
  { concept: "The Yoke of Equanimity", tradition: "Bhagavad Gita", source: "Bhagavad Gita 6.7", explanation: "For the yogi who is established in the Self, the Self becomes a friend; but for one who is not so established, the Self acts as an enemy. The mind is the battlefield — the Gita's literal meaning of 'yoga' as union through discipline.", application: "Treat the mind as a training ground, not a battlefield to win. The goal is not to defeat thoughts but to befriend the one who watches them.", questions: ["Is my Self currently my friend or my enemy?", "What would befriending my mind look like this week?", "Where am I fighting myself instead of training myself?"], references: ["Bhagavad Gita 6.5-6.7", "Bhagavad Gita 6.34-6.35"], excerpt: "bandhur ātmātmanas tasya — For him, the Self is a friend.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["raja"], domains: ["growth", "self_care"], tags: ["gita", "equanimity", "self", "friend", "enemy"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Three Gunas — Modes of Nature", tradition: "Bhagavad Gita", source: "Bhagavad Gita 7.14, 14.5-14.20", explanation: "All of manifest nature operates through three modes: sattva (clarity, light, harmony), rajas (activity, passion, restlessness), and tamas (inertia, darkness, delusion). Everything you experience — including your own states — is a mixture of these three.", application: "Diagnose your current state: is this sattvic clarity, rajasic agitation, or tamasic heaviness? The diagnosis itself begins the shift — you cannot change what you cannot name.", questions: ["Which guna dominates my life this week?", "What food, work, and company feed each guna in me?", "What is one sattvic choice available today?"], references: ["Bhagavad Gita 14.5-14.20", "Bhagavad Gita 7.14", "Samkhya philosophy"], excerpt: "guṇa-traya-vibhāgaśaḥ — Divided into the three modes of nature.", evidence: "traditional", dimensions: ["thought", "emotion", "body"], paths: ["jnana", "raja"], domains: ["growth", "health"], tags: ["gita", "gunas", "sattva", "rajas", "tamas"], difficulty: "intermediate", minutes: 8 },
  { concept: "Devotion Without Anxiety", tradition: "Bhagavad Gita", source: "Bhagavad Gita 7.14, 9.22", explanation: "The divine maya of the gunas is difficult to cross — but those who take refuge in the divine cross it. And to those who are constantly devoted and worship with love, the Gita promises: I give them the yoga of discernment, by which they come to me.", application: "Devotion is presented not as blind faith but as a sustained orientation of the heart — a practice of taking refuge, which the text itself describes as the crossing mechanism.", questions: ["What do I take refuge in when things collapse?", "Is my devotion anxious or settled?", "What would 'constant devotion' look like in ordinary Tuesday terms?"], references: ["Bhagavad Gita 7.14", "Bhagavad Gita 9.22", "Bhagavad Gita 12.13-12.20"], excerpt: "ananyāś cintayanto māṁ — Those who worship with exclusive devotion.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["bhakti"], domains: ["spirituality", "growth"], tags: ["gita", "devotion", "bhakti", "refuge", "maya"], difficulty: "intermediate", minutes: 7 },
  { concept: "Offer Me a Leaf, a Flower, a Fruit, Water", tradition: "Bhagavad Gita", source: "Bhagavad Gita 9.26", explanation: "If one offers me a leaf, a flower, a fruit, or even water, offered with devotion, I accept it. The Gita democratizes worship — the offering's value is not its cost but the devotion behind it.", application: "Make the next meal, the next breath, the next small act an offering. The scale of the offering is irrelevant; the orientation is everything.", questions: ["What can I offer today — even water?", "What is the difference between a transaction and an offering?", "Where is devotion hiding in my ordinary actions?"], references: ["Bhagavad Gita 9.26", "Bhagavad Gita 9.27"], excerpt: "patraṁ puṣpaṁ phalaṁ toyaṁ — A leaf, a flower, a fruit, or water.", evidence: "traditional", dimensions: ["spirit", "action"], paths: ["bhakti", "karma"], domains: ["spirituality", "self_care"], tags: ["gita", "offering", "devotion", "leaf", "flower"], difficulty: "beginner", minutes: 5 },
  { concept: "Time I Am — The Destroyer of Worlds", tradition: "Bhagavad Gita", source: "Bhagavad Gita 11.32", explanation: "In the vision of the universal form, Krishna declares: I am time, the destroyer of worlds, grown mature, engaged in destroying the worlds. Even without you, the warriors arrayed in the opposing army shall not live. The teaching: cosmic processes operate whether or not we participate in them anxiously.", application: "When you feel personally responsible for outcomes beyond your control, recall the universal form: the processes are vast, and your duty is the action, not the cosmic result.", questions: ["What cosmic-scale process am I anxiously trying to control?", "What is my actual scope of action?", "How does seeing the bigger frame change today's priority?"], references: ["Bhagavad Gita 11.32", "Bhagavad Gita 11.12-11.35"], excerpt: "kālo'smi lokakṣayakṛt — I am time, the destroyer of worlds.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana", "bhakti"], domains: ["purpose", "growth"], tags: ["gita", "time", "universal_form", "vishvarupa", "perspective"], difficulty: "advanced", minutes: 8 },
  { concept: "The Qualities of the Devoted", tradition: "Bhagavad Gita", source: "Bhagavad Gita 12.13-12.20", explanation: "The Gita's precise portrait of the devotee: one who is inimical to no being, friendly and compassionate, free from possessiveness and ego, even-minded in happiness and distress, forgiving, always content, engaged in devotion with self-control. A checklist of character, not emotion.", application: "Use the twelve qualities as a monthly character audit. Not 'do I feel devotion' but 'am I forgiving, content, even-minded' — the Gita measures devotion by conduct.", questions: ["Which of the twelve qualities is strongest in me today?", "Which is weakest, and what would one small act of it look like?", "Is my devotion emotional or behavioral — and does the difference matter?"], references: ["Bhagavad Gita 12.13-12.20"], excerpt: "adveṣṭā sarva-bhūtānāṁ — Inimical to no being.", evidence: "traditional", dimensions: ["emotion", "connection", "action"], paths: ["bhakti"], domains: ["growth", "relationships"], tags: ["gita", "devotion", "qualities", "character", "checklist"], difficulty: "beginner", minutes: 7 },
  { concept: "The Field and the Knower of the Field", tradition: "Bhagavad Gita", source: "Bhagavad Gita 13.1-13.3", explanation: "This body is the field (kshetra); the one who knows it is the knower of the field (kshetrajna). The Gita distinguishes the known from the knower — the entire manifest world is the field, and awareness is its knower.", application: "In any experience, ask: what is the field (the known — body, emotion, situation) and what is the knower? Confusing the two is the root of suffering; distinguishing them is the root of freedom.", questions: ["In my current difficulty, what is the field and what is the knower?", "Where do I mistake the known for the knower?", "What becomes possible when the distinction is held?"], references: ["Bhagavad Gita 13.1-13.3", "Bhagavad Gita 13.20-13.25"], excerpt: "kṣetra-kṣetrajñayor evam antaraṁ jñāna-cakṣuṣā — Thus the field and the knower of the field.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana", "raja"], domains: ["spirituality", "growth"], tags: ["gita", "field", "knower", "kshetra", "kshetrajna"], difficulty: "advanced", minutes: 8 },
  { concept: "The Divine and Demoniac Qualities", tradition: "Bhagavad Gita", source: "Bhagavad Gita 16.1-16.22", explanation: "The Gita catalogs two natures: the divine (daivi) — fearlessness, purity of heart, perseverance in knowledge and action, charity, self-control, sacrifice, study, austerity, honesty; and the demoniac (asuri) — hypocrisy, arrogance, conceit, anger, harshness, ignorance. The lists are diagnostic, not decorative.", application: "Score yourself honestly on the two lists. The point is not shame but direction — the divine qualities are practices, not traits you either have or lack.", questions: ["Which three divine qualities do I practice most?", "Which demoniac quality visits me most often, and what is its trigger?", "What is one divine quality I can practice this week?"], references: ["Bhagavad Gita 16.1-16.22"], excerpt: "abhayaṁ sattva-saṁśuddhir — Fearlessness, purity of heart.", evidence: "traditional", dimensions: ["thought", "emotion", "action"], paths: ["jnana", "karma"], domains: ["growth"], tags: ["gita", "daivi", "asuri", "qualities", "diagnosis"], difficulty: "intermediate", minutes: 8 },
  { concept: "The Threefold Austerity", tradition: "Bhagavad Gita", source: "Bhagavad Gita 17.14-17.16", explanation: "Austerity of body: worship of the divine, the twice-born, the teacher; cleanliness, straightness, celibacy, non-violence. Austerity of speech: speech that causes no agitation, truthful, pleasant, beneficial, regular study of scripture. Austerity of mind: serenity, gentleness, silence, self-restraint, purity of heart.", application: "The Gita's three-fold tapas reframes discipline: it is not deprivation but the training of body, speech, and mind. Audit all three — most people train one and neglect two.", questions: ["Which austerity do I practice — body, speech, or mind?", "Is my speech austerity-worthy — truthful, pleasant, beneficial?", "What is one act of mental austerity available today (serenity, silence, gentleness)?"], references: ["Bhagavad Gita 17.14-17.16", "Bhagavad Gita 17.17"], excerpt: "kāyena vācasa manasā — Austerity of body, speech, and mind.", evidence: "traditional", dimensions: ["action", "thought", "body"], paths: ["raja", "karma"], domains: ["growth", "work"], tags: ["gita", "austerity", "tapas", "body", "speech", "mind"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Three Divisions of Faith", tradition: "Bhagavad Gita", source: "Bhagavad Gita 17.1-17.3", explanation: "Faith is of three kinds, according to the three gunas: sattvic faith seeks the truth and persists; rajasic faith is restless, seeking results; tamasic faith is lazy, deluded, attached to ritual without understanding. Even faith has a quality, not just a quantity.", application: "Examine not whether you believe, but the quality of your believing. Is your faith clear and patient, anxious and grasping, or dull and mechanical?", questions: ["What is the guna-quality of my current faith or conviction?", "Where is my faith rajasic — demanding results?", "Where is it tamasic — going through motions?"], references: ["Bhagavad Gita 17.1-17.3", "Bhagavad Gita 17.4-17.10"], excerpt: "śraddhā tri-vidhā — Faith is threefold.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana", "bhakti"], domains: ["spirituality", "growth"], tags: ["gita", "faith", "shraddha", "gunas", "quality"], difficulty: "advanced", minutes: 7 },
  { concept: "The Conclusion — Sarva Dharma Parityajya", tradition: "Bhagavad Gita", source: "Bhagavad Gita 18.66", explanation: "The Gita's final instruction: abandon all dharmas and take refuge in me alone. I will liberate you from all sins; do not grieve. After eighteen chapters of yoga, knowledge, and action, the teaching collapses into a single act of surrender.", application: "Interpreted for daily life: after all practices, analyses, and efforts, there is a final letting go — the release of every method into trust. The methods are the path; the surrender is the arrival.", questions: ["What am I still gripping that the final instruction asks me to release?", "What would 'taking refuge' mean in my life today — not religiously, but practically?", "Can I distinguish the method from the arrival?"], references: ["Bhagavad Gita 18.66", "Bhagavad Gita 18.62-18.65"], excerpt: "sarva-dharmān parityajya mām ekaṁ śaraṇaṁ vraja — Abandon all dharmas; take refuge in me alone.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["bhakti", "jnana"], domains: ["spirituality"], tags: ["gita", "surrender", "conclusion", "refuge", "final_teaching"], difficulty: "advanced", minutes: 8 },
  { concept: "The Yoga of the Gita Itself", tradition: "Bhagavad Gita", source: "Bhagavad Gita 18.78", explanation: "The Gita closes with Sanjaya's vision: wherever there is Krishna, the master of yoga, and wherever there is Arjuna, the archer, there is prosperity, victory, happiness, and firm policy. The text frames itself as the complete teaching — the field, the archer, and the guide.", application: "The Gita's final image is relational: the guide and the archer, the teacher and the practitioner. No teaching completes itself without the one who practices it. Your life is the battlefield; the teaching is the chariot.", questions: ["Who is my charioteer — what guidance do I actually listen to?", "Where is my battlefield — the arena where I must act?", "What would 'firm policy' — settled conviction — look like in my life?"], references: ["Bhagavad Gita 18.78", "Bhagavad Gita 18.75-18.78"], excerpt: "yatra yogeśvaraḥ kṛṣṇo yatra pārtho dhanur-dharaḥ — Wherever is the master of yoga and the archer Arjuna.", evidence: "traditional", dimensions: ["spirit", "action"], paths: ["raja", "karma"], domains: ["spirituality", "purpose"], tags: ["gita", "conclusion", "charioteer", "archer", "victory"], difficulty: "intermediate", minutes: 6 },
];

export const WISDOM_UPANISHADS: WisdomArchetype[] = [
  { concept: "Tat Tvam Asi — Thou Art That", tradition: "Upanishads", source: "Chandogya Upanishad 6.8.7", explanation: "The Mahavakya of the Chandogya: Uddalaka Aruni teaches his son Shvetaketu that the self in all beings is one — 'that thou art.' The individual self and the universal reality are not similar; they are identical.", application: "When the sense of smallness or separation is strong, recall the teaching's direct claim: not 'you are like the whole' but 'you are that.' The distinction is the entire teaching.", questions: ["What would change if 'thou art that' were literally true?", "Where do I experience separation most strongly?", "What is the difference between being like the whole and being it?"], references: ["Chandogya Upanishad 6.8.7", "Brihadaranyaka Upanishad", "Advaita Vedanta"], excerpt: "tat tvam asi — Thou art that.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana"], domains: ["spirituality"], tags: ["upanishads", "tat_tvam_asi", "mahavakya", "identity", "non_dual"], difficulty: "advanced", minutes: 8 },
  { concept: "Aham Brahmasmi — I Am Brahman", tradition: "Upanishads", source: "Brihadaranyaka Upanishad 1.4.10", explanation: "The Brihadaranyaka's Mahavakya: in the beginning, this was only the Self, in the form of a person; it looked around and saw nothing but itself. 'I am Brahman' — the first-person declaration of identity with the whole.", application: "The declaration is not vanity but the correction of its opposite — the habitual understatement of the self as a small, separate, anxious entity. The practice is to test the claim against experience.", questions: ["What do I take myself to be, when I take myself seriously?", "What is the difference between 'I am Brahman' and 'I am important'?", "Where in daily life would this declaration change a decision?"], references: ["Brihadaranyaka Upanishad 1.4.10", "Mandukya Upanishad"], excerpt: "aham brahmāsmi — I am Brahman.", evidence: "traditional", dimensions: ["spirit"], paths: ["jnana"], domains: ["spirituality"], tags: ["upanishads", "aham_brahmasmi", "mahavakya", "brahman", "identity"], difficulty: "advanced", minutes: 8 },
  { concept: "Ayam Atma Brahma — This Self Is Brahman", tradition: "Upanishads", source: "Mandukya Upanishad 2", explanation: "The Mandukya's Mahavakya: this Self is Brahman. The shortest of the four great declarations — 'this' self, here, now, is the whole. No journey, no becoming, only recognition.", application: "The teaching removes the distance between practice and realization: the self you are looking for is the one looking. Recognition, not acquisition.", questions: ["What am I searching for that is already the searcher?", "What is the difference between acquiring and recognizing?", "Can 'this self, here, now' be tested directly?"], references: ["Mandukya Upanishad 2", "Mandukya Karika"], excerpt: "ayam ātmā brahma — This Self is Brahman.", evidence: "traditional", dimensions: ["spirit"], paths: ["jnana", "raja"], domains: ["spirituality"], tags: ["upanishads", "ayam_atma_brahma", "mahavakya", "mandukya", "recognition"], difficulty: "advanced", minutes: 7 },
  { concept: "Prajnanam Brahma — Consciousness Is Brahman", tradition: "Upanishads", source: "Aitareya Upanishad 3.3", explanation: "The Aitareya's Mahavakya: consciousness is Brahman. The teaching locates the absolute not in a distant heaven but in the very fact of awareness — the knowing that precedes every known.", application: "When philosophy feels abstract, return to the plainest fact: something is aware right now. The teaching says that awareness itself is the subject of all teachings.", questions: ["Can I find the awareness that is reading this?", "What is the difference between being conscious and being conscious of something?", "Why does the teaching begin with consciousness rather than with God or cosmos?"], references: ["Aitareya Upanishad 3.3", "Taittiriya Upanishad"], excerpt: "prajñānaṁ brahma — Consciousness is Brahman.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana"], domains: ["spirituality"], tags: ["upanishads", "prajnanam_brahma", "mahavakya", "consciousness", "awareness"], difficulty: "advanced", minutes: 7 },
  { concept: "Neti Neti — Not This, Not This", tradition: "Upanishads", source: "Brihadaranyaka Upanishad 2.3.6", explanation: "The method of negation: the Self is not this, not this. Every describable, graspable, nameable thing is set aside — body, mind, role, emotion, thought — until what remains is not a thing at all but the witnessing itself.", application: "Use neti neti as a daily subtraction: when you claim an identity, ask 'is this the self or an object the self is aware of?' Keep subtracting. What remains is the teaching.", questions: ["What am I still claiming as 'me' that is an object of awareness?", "What survives the subtraction of every role?", "Is the witness an object? Can it be subtracted?"], references: ["Brihadaranyaka Upanishad 2.3.6", "Brihadaranyaka Upanishad 4.5.15"], excerpt: "neti neti — Not this, not this.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana"], domains: ["spirituality", "growth"], tags: ["upanishads", "neti_neti", "negation", "method", "subtraction"], difficulty: "advanced", minutes: 8 },
  { concept: "The Two Birds on the Same Tree", tradition: "Upanishads", source: "Mundaka Upanishad 3.1.1", explanation: "Two birds, inseparable companions, perch on the same tree. One eats the fruit; the other looks on without eating. The first is the engaged self; the second is the witness. The tree is the body; the fruits are experience.", application: "In any intense experience, locate the second bird — the one who looks on without eating. The practice is not to stop eating but to know the watcher is always present.", questions: ["In my current struggle, which bird am I identified with?", "Can I find the second bird in a moment of pleasure, not just pain?", "What changes when both birds are known as one self?"], references: ["Mundaka Upanishad 3.1.1", "Rig Veda 1.164.20", "Bhagavad Gita 13.1-13.3"], excerpt: "dve suparnā sayujā sakhāyā — Two birds, inseparable companions, on the same tree.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana", "raja"], domains: ["spirituality"], tags: ["upanishads", "two_birds", "mundaka", "witness", "tree"], difficulty: "intermediate", minutes: 7 },
  { concept: "Nachiketa and the Three Boons", tradition: "Upanishads", source: "Katha Upanishad 1.1", explanation: "Young Nachiketa, sent to death by his father, meets Yama, the lord of death. His three boons: to be reconciled, to know the fire sacrifice that reaches heaven, and — the third, refused twice by Yama — to know what happens after death. The Katha's frame story is itself a teaching about what questions are worth asking.", application: "Examine your own third boons: what question do you keep asking that life keeps refusing to answer? The refusal is part of the teaching — the question that matters is never cheaply granted.", questions: ["What is my third boon — the question I keep asking?", "What have I settled for instead of asking it?", "What would I do with the answer, if it came?"], references: ["Katha Upanishad 1.1-1.3"], excerpt: "The boy Nachiketa, standing at the threshold of death, asks what lies beyond.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana"], domains: ["spirituality", "purpose"], tags: ["upanishads", "nachiketa", "yama", "death", "three_boons"], difficulty: "intermediate", minutes: 8 },
  { concept: "The Chariot — Body, Mind, Intellect, Self", tradition: "Upanishads", source: "Katha Upanishad 1.3.3-1.3.9", explanation: "The self is the rider; the body is the chariot; the intellect is the charioteer; the mind is the reins; the senses are the horses; the objects of the senses are the roads. The Katha's complete map of the human apparatus — and the diagnosis of most suffering: undisciplined horses, careless reins, lost charioteer.", application: "Diagnose your own chariot: are the senses (horses) running where they please? Are the reins (mind) steady? Is the intellect (charioteer) awake? Is the self (rider) even present?", questions: ["In my life, who is driving — intellect or senses?", "Where are my reins slack?", "When did I last notice the rider, not just the ride?"], references: ["Katha Upanishad 1.3.3-1.3.9"], excerpt: "The self is the rider, the body the chariot, the intellect the charioteer, the mind the reins.", evidence: "traditional", dimensions: ["thought", "body", "spirit"], paths: ["jnana", "raja"], domains: ["learning", "growth"], tags: ["upanishads", "chariot", "katha", "body", "mind", "intellect"], difficulty: "beginner", minutes: 6 },
  { concept: "The Five Sheaths — Pancha Kosha", tradition: "Upanishads", source: "Taittiriya Upanishad 2.1-2.7", explanation: "The self is covered by five sheaths: the physical (annamaya), the vital (pranamaya), the mental (manomaya), the intellectual (vijnanamaya), and the blissful (anandamaya). The Taittiriya's map explains why we mistake coverings for the covered.", application: "When you feel 'not yourself,' ask which sheath is speaking — the body's fatigue, the breath's agitation, the mind's noise, the intellect's confusion, or the bliss sheath's absence. Each sheath has its own medicine.", questions: ["Which sheath is loudest in me today?", "Have I ever mistaken a sheath for the self?", "What does each sheath need — food, breath, attention, clarity, rest?"], references: ["Taittiriya Upanishad 2.1-2.7", "Taittiriya Upanishad 3.6"], excerpt: "Annamaya kośaḥ... prāṇamayaḥ... manomayaḥ... vijñānamayaḥ... ānandamayaḥ — The five sheaths.", evidence: "traditional", dimensions: ["body", "thought", "spirit"], paths: ["jnana", "hatha"], domains: ["health", "learning"], tags: ["upanishads", "pancha_kosha", "sheaths", "taittiriya", "layers"], difficulty: "intermediate", minutes: 8 },
  { concept: "The Honey Doctrine — Madhu Vidya", tradition: "Upanishads", source: "Brihadaranyaka Upanishad 2.5", explanation: "The Brihadaranyaka's honey doctrine: as waters flow from all directions into the ocean and become one, losing their separate identities, so all beings flow into the one Self. The teaching of convergence — the many returning to the one without losing their essence.", application: "In conflict or multiplicity, recall the ocean: the streams keep their courses but lose their separateness in the whole. The practice is to see the convergence, not the collision.", questions: ["Where in my life are streams insisting on separate identity?", "What would convergence look like in this relationship?", "Can I see the ocean without erasing the streams?"], references: ["Brihadaranyaka Upanishad 2.5.1-2.5.10"], excerpt: "As rivers flow into the sea, losing name and form, so the knower becomes one with the one.", evidence: "traditional", dimensions: ["spirit", "connection"], paths: ["jnana"], domains: ["spirituality", "relationships"], tags: ["upanishads", "honey_doctrine", "madhu_vidya", "convergence", "ocean"], difficulty: "advanced", minutes: 8 },
  { concept: "The Golden Lid — Hiranyagarbha", tradition: "Upanishads", source: "Isha Upanishad 15", explanation: "The Isha Upanishad's prayer: push back the golden lid, O Sun, that I may see your true form. The golden lid is the veil of maya — the brilliance that both reveals and conceals. The prayer asks not for more light but for the removal of the obstruction to light already present.", application: "The teaching reframes seeking: the obstacle is not absence but obstruction. The practice is not to acquire light but to push back the lid — attention, inquiry, surrender are the pushing.", questions: ["What is my golden lid — what obscures what is already present?", "Am I trying to acquire what I need only to uncover?", "What pushes the lid back for me — silence, inquiry, devotion?"], references: ["Isha Upanishad 15", "Isha Upanishad 16-18"], excerpt: "hiraṇmayeṇa pātreṇa satyasyapihitam mukham — The golden lid covering the face of truth.", evidence: "traditional", dimensions: ["spirit"], paths: ["jnana", "bhakti"], domains: ["spirituality"], tags: ["upanishads", "golden_lid", "isha", "veil", "maya"], difficulty: "advanced", minutes: 7 },
  { concept: "The Eye Cannot Reach It", tradition: "Upanishads", source: "Kena Upanishad 1.1-1.3", explanation: "The Kena's opening mystery: by whom does the mind think? By whom does the eye see? By whom does the ear hear? What you cannot see with the eye, but by which the eye sees — that alone is Brahman. The teaching points to the precondition of every faculty.", application: "For each faculty, ask the Kena question: what makes it possible? The answer is never another faculty — it is the awareness that uses them all. The question itself is the practice.", questions: ["By whom does my mind think, right now?", "What is the difference between the eye and the one by which the eye sees?", "Can I find the precondition of my own awareness?"], references: ["Kena Upanishad 1.1-1.3", "Kena Upanishad 2.1-2.5"], excerpt: "cakṣuṣā cakṣuṁ na paśyati... — The eye cannot see it; it is that by which the eye sees.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana"], domains: ["spirituality"], tags: ["upanishads", "kena", "eye", "precondition", "mystery"], difficulty: "advanced", minutes: 8 },
  { concept: "The Four Quarters — Turiya", tradition: "Upanishads", source: "Mandukya Upanishad 1-12", explanation: "The Mandukya maps consciousness in four quarters: waking (jagrat), dreaming (swapna), deep sleep (sushupti), and the fourth (turiya) — not a state among states but the awareness in which all three arise. Turiya is described as soundless, intangible, formless, indestructible, serene.", application: "The Mandukya's method: notice the three states you already pass through daily, and inquire into the one that never changes. Sleep and waking are objects; the fourth is the subject.", questions: ["Can I distinguish the three states I pass through from the one I never leave?", "What was aware of my dreamless sleep?", "Is turiya a state to enter or a recognition to make?"], references: ["Mandukya Upanishad 1-12", "Mandukya Karika"], excerpt: "caturthaḥ — the fourth. Soundless, intangible, formless, indestructible.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana", "raja"], domains: ["spirituality"], tags: ["upanishads", "mandukya", "turiya", "four_quarters", "states"], difficulty: "advanced", minutes: 10 },
  { concept: "Sat-Chit-Ananda — Being, Awareness, Bliss", tradition: "Upanishads", source: "Taittiriya Upanishad 3.6; Chandogya 7", explanation: "The Upanishads describe brahman's nature in three words: sat (existence itself), chit (awareness itself), ananda (bliss itself). Not three properties of a thing but three inadequate words pointing to one reality that is, that knows, that is joy.", application: "The triple description is a contemplative sequence: rest in existence (I am), then in awareness (I know), then in the bliss that is not an emotion but the nature of awareness itself.", questions: ["Can I distinguish existing from knowing from being joyful?", "Is ananda an emotion or the nature of awareness?", "What is the simplest test of sat — that I am?"], references: ["Taittiriya Upanishad 3.6", "Chandogya Upanishad 7", "Brihadaranyaka Upanishad 3.9.28"], excerpt: "satyam jñānam anantam brahma — Truth, knowledge, infinity is Brahman.", evidence: "traditional", dimensions: ["spirit"], paths: ["jnana"], domains: ["spirituality"], tags: ["upanishads", "sat_chit_ananda", "brahman", "existence", "bliss"], difficulty: "advanced", minutes: 8 },
  { concept: "The Doctrine of the Five Elements", tradition: "Upanishads", source: "Chandogya Upanishad 6.1-6.8; Taittiriya 1.7", explanation: "Uddalaka Aruni's teaching to Shvetaketu: from the subtle emerge the gross — ether, air, fire, water, earth — each finer preceding each coarser. The same teaching appears in the Taittiriya's account of creation from the self. The cosmos is a process of differentiation from the one.", application: "The elements teaching is the original systems view: everything manifest is a condensation of the subtle. In daily life, notice the pattern — subtle intentions become gross actions; subtle moods become gross conflicts.", questions: ["What subtle element is condensing into a gross problem in my life?", "Where is the subtle hiding inside the gross?", "How does the teaching change my sense of what is 'real'?"], references: ["Chandogya Upanishad 6.1-6.8", "Taittiriya Upanishad 2.1"], excerpt: "From the subtle, O Shvetaketu, comes the gross. This is the truth.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["learning", "spirituality"], tags: ["upanishads", "five_elements", "pancha_bhuta", "subtle", "gross"], difficulty: "intermediate", minutes: 8 },
  { concept: "Uddalaka's Nine Similes", tradition: "Upanishads", source: "Chandogya Upanishad 6.1-6.16", explanation: "To teach the self's presence in all things, Uddalaka uses nine similes: the seed and the tree, the salt in water, the rivers and the ocean, the tree and its sap, the honey and its flowers, the city and its roads, the self in the body. The method: the one is hidden in the many, as salt is hidden in water — invisible, yet present in every drop.", application: "Use the similes as contemplations: the salt in water is the classic. Stir salt into water; taste it everywhere. The self is not in some parts of experience but in every part.", questions: ["Which simile makes the teaching most vivid for me?", "Where do I look for the self as if it were only in some experiences?", "What is the salt-in-water test of my own attention?"], references: ["Chandogya Upanishad 6.1-6.16"], excerpt: "As salt in water — invisible, yet present in every drop. That which is the subtle essence, that is the self.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana"], domains: ["spirituality", "learning"], tags: ["upanishads", "similes", "uddalaka", "salt", "chandogya"], difficulty: "intermediate", minutes: 8 },
  { concept: "Yajnavalkya's Teaching on the Self", tradition: "Upanishads", source: "Brihadaranyaka Upanishad 3.7-4.5", explanation: "Yajnavalkya's long instruction: the self is the inner controller, present in all beings, distinct from them, unseen but seeing, unheard but hearing, unthought but thinking. The Brihadaranyaka's most sustained portrait of the witness as the inner controller (antaryamin).", application: "The inner controller teaching is the basis for the witness practice: in every action, something is present that is not the doer. Notice the controller, not the controlled.", questions: ["Who is the inner controller of my current activity?", "What is the difference between the doer and the inner controller?", "Can I act while resting as the controller, not the controlled?"], references: ["Brihadaranyaka Upanishad 3.7", "Brihadaranyaka Upanishad 4.5"], excerpt: "The self is the inner controller, the immortal, the unseen but seeing.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana", "raja"], domains: ["spirituality"], tags: ["upanishads", "yajnavalkya", "inner_controller", "antaryamin", "witness"], difficulty: "advanced", minutes: 9 },
  { concept: "The Teaching of Prana", tradition: "Upanishads", source: "Kaushitaki Upanishad 1-2; Prashna Upanishad 2-3", explanation: "The Kaushitaki and Prashna Upanishads examine prana — the vital force — as the thread on which all functions hang. When prana departs, the senses depart. The teaching: vitality is the bridge between body and consciousness.", application: "The prana teaching grounds breathwork in metaphysics: the breath is not merely physiological but the visible edge of the vital force. Breath practices become prana practices.", questions: ["Where is my prana most alive right now?", "What is the relationship between my breath and my attention?", "How does the prana teaching change my view of breathwork?"], references: ["Kaushitaki Upanishad 1-2", "Prashna Upanishad 2-3", "Chandogya Upanishad 1.11"], excerpt: "As long as prana remains in the body, so long do the senses abide.", evidence: "traditional", dimensions: ["body", "spirit"], paths: ["kriya", "hatha"], domains: ["health", "spirituality"], tags: ["upanishads", "prana", "vital_force", "breath", "kaushitaki"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Sixteen Parts of the Self", tradition: "Upanishads", source: "Prashna Upanishad 7", explanation: "The Prashna Upanishad's account of the self's sixteen parts — from prana and faith through the elements, organs, and food — culminating in the teaching that the self is beyond all parts. The parts are the map; the self is not on the map.", application: "Use the sixteen parts as a completeness check: am I attending to only one part (the body, the mind) while the teaching concerns the whole? The map's purpose is to be transcended.", questions: ["Which of my sixteen parts do I attend to most?", "Which do I neglect?", "What is beyond all parts — and how would I know it?"], references: ["Prashna Upanishad 7", "Prashna Upanishad 1-6"], excerpt: "The self's sixteen parts — prana, faith, space, air, fire, water, earth...", evidence: "traditional", dimensions: ["spirit", "thought", "body"], paths: ["jnana"], domains: ["learning", "spirituality"], tags: ["upanishads", "prashna", "sixteen_parts", "map", "beyond"], difficulty: "advanced", minutes: 8 },
  { concept: "Shvetashvatara's Rudra — The One Behind the Three Gunas", tradition: "Upanishads", source: "Shvetashvatara Upanishad 1-4", explanation: "The Shvetashvatara teaches the one Rudra beyond the three gunas, the one who creates the gods and presides over all, hidden in all beings as the inner self. The text bridges the Upanishads' impersonal brahman and the devotional theism that follows.", application: "The teaching offers a third option beyond impersonal absolute and personal God: the one behind the gunas, accessible through both inquiry and devotion. The practitioner may use either door.", questions: ["Do I relate to the teaching as impersonal awareness or as a presence?", "What is behind the gunas in my own experience?", "Can both doors — inquiry and devotion — be true?"], references: ["Shvetashvatara Upanishad 1.8-1.13", "Shvetashvatara Upanishad 3.2", "Shvetashvatara Upanishad 4.1-4.14"], excerpt: "ekam evādvitīyaṁ — One only, without a second.", evidence: "traditional", dimensions: ["spirit"], paths: ["bhakti", "jnana"], domains: ["spirituality"], tags: ["upanishads", "shvetashvatara", "rudra", "gunas", "theism"], difficulty: "advanced", minutes: 8 },
  { concept: "The Fire of Knowledge", tradition: "Upanishads", source: "Mundaka Upanishad 1.2; 3.1", explanation: "The Mundaka distinguishes two kinds of knowledge: the lower (vidya) — the Vedas, ritual, grammar, astronomy — and the higher (para vidya) — that by which the immortal is known. The lower is useful; the higher is liberating. The text is blunt: the lower cannot take you to the higher.", application: "Audit your own knowledge diet: how much is lower knowledge (information, skill, technique) and how much is higher (the inquiry into what knows)? Both are needed; only one liberates.", questions: ["What is my lower knowledge serving?", "Where is my higher knowledge practice?", "Can I distinguish information from inquiry in my daily learning?"], references: ["Mundaka Upanishad 1.1.4-1.1.5", "Mundaka Upanishad 1.2.1-1.2.13"], excerpt: "dve vidyā veditavye iti ha sma yad brahma-vido vadanti — Two kinds of knowledge, say those who know Brahman.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["learning", "spirituality"], tags: ["upanishads", "mundaka", "two_knowledges", "para_vidya", "apara_vidya"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Bow and the Arrow — Om as the Bow", tradition: "Upanishads", source: "Mundaka Upanishad 2.2.4", explanation: "The Mundaka's famous image: the syllable om is the bow; the self is the arrow; brahman is the target. The instruction: shoot with the bow of om, aiming at the target of brahman, with the self as arrow. Concentration is archery.", application: "The image gives meditation a clear structure: the bow (the mantra or method), the arrow (the self, your attention), the target (brahman, the real). Aim deliberately; the arrow is you.", questions: ["What is my bow — my method?", "What is my target?", "How steadily do I aim, versus how often do I loose arrows randomly?"], references: ["Mundaka Upanishad 2.2.4", "Mundaka Upanishad 2.2.5-2.2.8"], excerpt: "oṁ ity ekākṣaraṁ brahma — Om, the one syllable, is the bow.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["raja", "jnana"], domains: ["spirituality", "learning"], tags: ["upanishads", "bow", "arrow", "om", "mundaka"], difficulty: "intermediate", minutes: 6 },
  { concept: "The City of Eleven Gates", tradition: "Upanishads", source: "Katha Upanishad 2.1.1; Bhagavad Gita 5.13", explanation: "The Katha's image: the self dwells in the city of eleven gates (the body with its ten senses and mind). The wise one, leaving the city, grieves no more. The city is not the self; confusing them is the original error.", application: "When identity feels trapped in the body's story, recall the city image: you are not the city but its dweller — and the dweller can leave the city's affairs without abandoning the city.", questions: ["Am I the city or the dweller?", "What are my eleven gates — which senses dominate my attention?", "What does it mean to leave the city without fleeing it?"], references: ["Katha Upanishad 2.1.1", "Bhagavad Gita 5.13", "Brihadaranyaka Upanishad 2.1.18"], excerpt: "The self, dwelling in the city of eleven gates, grieves no more when it leaves the city.", evidence: "traditional", dimensions: ["spirit", "body"], paths: ["jnana", "raja"], domains: ["spirituality", "growth"], tags: ["upanishads", "city", "eleven_gates", "katha", "body"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Raft — The Teaching as a Raft", tradition: "Upanishads", source: "Mundaka Upanishad 1.2.7; Brihadaranyaka 4.5.15", explanation: "The Mundaka's image: the teaching is a raft, to be used for crossing. The river is the world of ignorance; the far shore is the known self. The raft is not the destination — the wise one, having crossed, leaves the raft on the shore.", application: "Hold every method — practice, text, teacher, experience — as a raft. Useful for crossing; burdensome if carried. The teaching that becomes identity becomes the obstacle it was meant to cross.", questions: ["Which raft am I currently using?", "Where am I carrying a raft I have already crossed by?", "What would it mean to leave this raft on the shore?"], references: ["Mundaka Upanishad 1.2.7", "Brihadaranyaka Upanishad 4.5.15", "Buddhist parable of the raft"], excerpt: "The teaching is a raft for crossing, not for holding.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["growth", "learning"], tags: ["upanishads", "raft", "crossing", "method", "letting_go"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Self in the Heart's Cave", tradition: "Upanishads", source: "Mundaka Upanishad 2.1.1; Chandogya 8.3-8.4", explanation: "The Mundaka: in the highest heaven is the purusha, the all-knowing, the source of all power, from whom the imperishable om arises. The Chandogya: the self dwells in the small space within the heart — the dahara, the little space, which contains all. The heart is the teaching's address.", application: "The heart-cave teaching gives inquiry a location: not the head but the chest. The practice of heart-centered meditation descends directly from these texts.", questions: ["Where do I locate my self — head, chest, or nowhere?", "What is the small space within the heart?", "Can I rest in the cave that contains all?"], references: ["Mundaka Upanishad 2.1.1", "Chandogya Upanishad 8.1-8.4", "Brihadaranyaka Upanishad 5.8"], excerpt: "In the small space within the heart dwells the self — all this is contained in it.", evidence: "traditional", dimensions: ["spirit", "body"], paths: ["raja", "jnana"], domains: ["spirituality"], tags: ["upanishads", "heart", "cave", "dahara", "chandogya"], difficulty: "advanced", minutes: 8 },
];

export const WISDOM_YOGA_SUTRAS: WisdomArchetype[] = [
  { concept: "Yoga Is the Cessation of Mental Fluctuations", tradition: "Yoga Sutras", source: "Yoga Sutras 1.2", explanation: "Patanjali's definition: yogas chitta vritti nirodhah — yoga is the cessation of the mind's fluctuations. Not the destruction of mind but the stilling of its turbulence, so that the seer can rest in its own nature.", application: "Every practice in the library serves this one definition. When a practice feels ineffective, ask: is it stilling fluctuations or adding more?", questions: ["What are my mind's dominant fluctuations today?", "Which practice stilled them most reliably?", "What is the difference between stilling and suppressing?"], references: ["Yoga Sutras 1.1-1.2", "Yoga Sutras 1.3-1.4"], excerpt: "yogaś citta-vṛtti-nirodhaḥ — Yoga is the cessation of the fluctuations of the mind.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["raja"], domains: ["spirituality", "learning"], tags: ["yoga_sutras", "patanjali", "chitta", "vritti", "nirodha"], difficulty: "beginner", minutes: 6 },
  { concept: "Then the Seer Abides in Its Own Nature", tradition: "Yoga Sutras", source: "Yoga Sutras 1.3", explanation: "The consequence of nirodha: tada drashtuh svarupe vasthanam — then the seer abides in its own form. The witness, freed from identification with the mind's contents, rests as itself. This is the goal stated in three words.", application: "The practice's purpose is not a special state but a return to the seer's own nature — ordinary, unmodified, present. Measure practices by whether they return you to the seer, not by experiences they produce.", questions: ["What is the seer's own nature, apart from everything it witnesses?", "When have I rested as the seer, even briefly?", "What pulls me back into identification?"], references: ["Yoga Sutras 1.3", "Yoga Sutras 1.4", "Yoga Sutras 4.18-4.26"], excerpt: "tadā draṣṭuḥ svarūpe vasthānam — Then the seer abides in its own nature.", evidence: "traditional", dimensions: ["spirit"], paths: ["raja", "jnana"], domains: ["spirituality"], tags: ["yoga_sutras", "seer", "drashtu", "svarupa", "own_nature"], difficulty: "intermediate", minutes: 7 },
  { concept: "Otherwise, Identification with Fluctuations", tradition: "Yoga Sutras", source: "Yoga Sutras 1.4", explanation: "Patanjali's diagnosis: vritti sarupyam itaratra — at other times, the seer identifies with the fluctuations. The mind's contents are mistaken for the self. This single sentence is the complete diagnosis of suffering in Patanjali's system.", application: "The sutra names the universal habit: taking the movie for the screen. The remedy is not to stop the movie but to stop the misidentification — the practice of every entry in this library.", questions: ["Which fluctuation am I currently identified with?", "What is the cost of this identification?", "What is the smallest act of disidentification available now?"], references: ["Yoga Sutras 1.4", "Yoga Sutras 2.6", "Yoga Sutras 2.17"], excerpt: "vṛtti-sārūpyam itaratra — Otherwise, identification with the fluctuations.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["raja", "jnana"], domains: ["growth", "learning"], tags: ["yoga_sutras", "identification", "vritti", "misidentification", "diagnosis"], difficulty: "beginner", minutes: 6 },
  { concept: "Practice and Dispassion", tradition: "Yoga Sutras", source: "Yoga Sutras 1.12-1.16", explanation: "The fluctuations are overcome by practice (abhyasa) and dispassion (vairagya). Practice is the effort to remain steady in stillness; dispassion is the cessation of craving, culminating in the letting go of even the gunas. The two wings of the entire path.", application: "Every session needs both: the effort to stay (abhyasa) and the release of the grip (vairagya). Too much practice without dispassion becomes striving; too much dispassion without practice becomes resignation.", questions: ["Is my current practice heavy on abhyasa or vairagya?", "What am I still craving from my practice?", "What would dispassion look like toward my own spiritual experiences?"], references: ["Yoga Sutras 1.12-1.16", "Yoga Sutras 2.1"], excerpt: "abhyāsa-vairāgyābhyāṁ tannirodhaḥ — They are overcome by practice and dispassion.", evidence: "traditional", dimensions: ["thought", "spirit", "action"], paths: ["raja", "jnana"], domains: ["growth", "spirituality"], tags: ["yoga_sutras", "abhyasa", "vairagya", "practice", "dispassion"], difficulty: "intermediate", minutes: 8 },
  { concept: "Practice Becomes Firmly Grounded", tradition: "Yoga Sutras", source: "Yoga Sutras 1.13-1.14", explanation: "Patanjali's definition of real practice: sa tu dirgha-kala-nairantarya-satkarasevito drdha-bhumih — practice becomes firmly grounded when cultivated for a long time, without interruption, with reverence. Three conditions: duration, continuity, and respect.", application: "The sutra is the antidote to spiritual consumerism. Measure your practice not by experiences but by the three conditions: how long, how unbroken, how reverent.", questions: ["How long have I practiced this — really?", "Where is the interruption pattern?", "What would 'reverence' add to my next session?"], references: ["Yoga Sutras 1.13-1.14", "Yoga Sutras 1.15-1.16"], excerpt: "Practice becomes firmly grounded when cultivated for a long time, without interruption, with reverence.", evidence: "traditional", dimensions: ["thought", "action"], paths: ["raja"], domains: ["growth", "discipline"], tags: ["yoga_sutras", "abhyasa", "long_time", "uninterrupted", "reverence"], difficulty: "beginner", minutes: 6 },
  { concept: "The Five Obstacles — Kleshas", tradition: "Yoga Sutras", source: "Yoga Sutras 2.3-2.11", explanation: "The five kleshas: ignorance (avidya), egoism (asmita), attachment (raga), aversion (dvesha), and clinging to life (abhinivesha). Ignorance is the field in which the others grow; the others are its shoots. The sutras map the entire structure of suffering.", application: "Use the five as a diagnostic: when suffering is present, name the klesha. Ignorance is the root — the others are its visible forms. The practice is not to fight the shoots but to light the root.", questions: ["Which klesha is active in my current difficulty?", "Where is ignorance operating as the root?", "What would 'lighting the root' look like today?"], references: ["Yoga Sutras 2.3-2.11", "Yoga Sutras 2.12-2.25"], excerpt: "avidyāsmitā-rāga-dveṣābhiniveśāḥ kleśāḥ — The five obstacles.", evidence: "traditional", dimensions: ["thought", "emotion", "spirit"], paths: ["jnana", "raja"], domains: ["growth", "learning"], tags: ["yoga_sutras", "kleshas", "avidya", "asmita", "raga", "dvesha", "abhinivesha"], difficulty: "intermediate", minutes: 9 },
  { concept: "Ignorance Is Taking the Non-Self for the Self", tradition: "Yoga Sutras", source: "Yoga Sutras 2.5", explanation: "Patanjali's precise definition of ignorance: taking the non-eternal for eternal, the impure for pure, suffering for pleasure, the non-self for the self. Ignorance is not lack of information — it is four specific misapprehensions.", application: "Test any strong attachment against the four: is this eternal? pure? pleasure? self? The misapprehension, once seen, loses much of its power — not because it is argued away but because it is seen.", questions: ["What am I taking to be eternal that is not?", "What am I calling pure that is impure?", "Where am I mistaking suffering for pleasure, the non-self for the self?"], references: ["Yoga Sutras 2.5", "Yoga Sutras 2.17-2.18"], excerpt: "anityāśuci-duḥkha-anātmasu nitya-śuci-sukha-ātma-khyātiḥ — Taking the non-eternal for eternal, the impure for pure.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["growth", "learning"], tags: ["yoga_sutras", "avidya", "ignorance", "misapprehension", "four_errors"], difficulty: "intermediate", minutes: 8 },
  { concept: "Egoism — The Seer Identifying with the Seen", tradition: "Yoga Sutras", source: "Yoga Sutras 2.6", explanation: "Asmita: the identification of the seer with the instrument of seeing. The power of sight mistakes itself for the seer. This is the subtle klesha — not a flaw of character but the structural error of consciousness mistaking its instrument for itself.", application: "Asmita explains why spiritual progress can inflate the ego: the instrument (mind, practice, insight) is mistaken for the seer. The antidote is not humility but accurate seeing — the instrument is seen, the seer sees.", questions: ["What instrument am I mistaking for the seer — mind, practice, insight, role?", "Where has spiritual progress fed asmita?", "What is the difference between the seer and the instrument of seeing?"], references: ["Yoga Sutras 2.6", "Yoga Sutras 2.17-2.20", "Yoga Sutras 4.18-4.19"], excerpt: "dṛg-dṛśya-svarūpābhimāsaḥ — The identification of the seer with the seen.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana", "raja"], domains: ["growth", "spirituality"], tags: ["yoga_sutras", "asmita", "egoism", "seer", "seen"], difficulty: "advanced", minutes: 8 },
  { concept: "The Eight Limbs — Ashtanga", tradition: "Yoga Sutras", source: "Yoga Sutras 2.29", explanation: "Patanjali's complete path: yama (restraints), niyama (observances), asana (posture), pranayama (breath regulation), pratyahara (sense withdrawal), dharana (concentration), dhyana (meditation), samadhi (absorption). Eight limbs, one tree — the most influential map of the path ever composed.", application: "The eight limbs are a completeness check for any practice life. Most modern practitioners live on limb three (asana) and occasionally limb four (pranayama). The sutras invite the whole tree.", questions: ["Which limbs do I practice — and which have I never touched?", "What would one small act of yama or niyama look like this week?", "Where does my practice sit on the eight-limb map?"], references: ["Yoga Sutras 2.29", "Yoga Sutras 2.30-2.34", "Yoga Sutras 2.46-2.53", "Yoga Sutras 3.1-3.8"], excerpt: "yama-niyamāsana-prāṇāyāma-pratyāhāra-dhāraṇā-dhyāna-samādhayo 'ṣṭāv aṅgāni — The eight limbs.", evidence: "traditional", dimensions: ["thought", "action", "spirit"], paths: ["raja"], domains: ["learning", "spirituality", "growth"], tags: ["yoga_sutras", "ashtanga", "eight_limbs", "yama", "niyama", "samadhi"], difficulty: "beginner", minutes: 9 },
  { concept: "The Yamas — Ahimsa First", tradition: "Yoga Sutras", source: "Yoga Sutras 2.30-2.35", explanation: "The five restraints: non-violence (ahimsa), truthfulness (satya), non-stealing (asteya), continence (brahmacharya), non-possessiveness (aparigraha). Patanjali's social ethics — the foundation without which the inner limbs are unstable. Ahimsa is named first and its fruit is named: when ahimsa is established, enmity ceases in one's presence.", application: "The yamas are practices, not virtues. Begin with ahimsa in its threefold form — not causing harm by thought, word, or deed — and notice what the sutra promises: not that others change, but that enmity ceases in your presence.", questions: ["Where is my ahimsa incomplete — thought, word, or deed?", "What would 'enmity ceases in my presence' require of me?", "Which yama is my weakest limb, and why?"], references: ["Yoga Sutras 2.30-2.35", "Yoga Sutras 2.36-2.39"], excerpt: "ahiṁsā-satya-asteya-brahmacarya-aparigrahāḥ yamāḥ — The five restraints.", evidence: "traditional", dimensions: ["action", "thought", "connection"], paths: ["raja", "karma"], domains: ["growth", "relationships"], tags: ["yoga_sutras", "yamas", "ahimsa", "satya", "asteya", "brahmacharya", "aparigraha"], difficulty: "beginner", minutes: 8 },
  { concept: "The Niyamas — Saucha and Santosha", tradition: "Yoga Sutras", source: "Yoga Sutras 2.32, 2.40-2.42", explanation: "The five observances: purity (shaucha), contentment (santosha), austerity (tapas), self-study (svadhyaya), and surrender to the lord (ishvara pranidhana). Patanjali's personal ethics — the inner counterpart of the yamas. From purity arises disgust with one's own body and realization of the self's purity; from contentment arises unsurpassed happiness.", application: "The niyamas are the inner laboratory. Santosha is the most counterintuitive: contentment is not resignation but the deliberate cessation of the mind's comparison engine. Practice it for one day and watch what happens.", questions: ["Which niyama is most alive in my life?", "Where is my contentment conditional?", "What would purity of body, speech, and mind change today?"], references: ["Yoga Sutras 2.32", "Yoga Sutras 2.40-2.42", "Yoga Sutras 2.43-2.45"], excerpt: "śauca-santoṣa-tapaḥ-svādhyāyeśvara-praṇidhānāni niyamāḥ — The five observances.", evidence: "traditional", dimensions: ["action", "thought", "emotion"], paths: ["raja", "kriya"], domains: ["growth", "self_care"], tags: ["yoga_sutras", "niyamas", "shaucha", "santosha", "tapas", "svadhyaya", "ishvara"], difficulty: "beginner", minutes: 8 },
  { concept: "Posture Is Steady and Comfortable", tradition: "Yoga Sutras", source: "Yoga Sutras 2.46-2.48", explanation: "Sthira sukham asanam — posture is steady and comfortable. Its mastery comes by relaxing effort and meditating on the infinite; then the pairs of opposites no longer disturb. The shortest, most quoted sutra on asana — and the most misunderstood. Asana is not exercise; it is the ability to sit still, comfortably, for the inner limbs.", application: "Test every physical practice against the two words: sthira (steady) and sukha (comfortable). A posture that cannot be held with both is not yet asana — it is gymnastics. The goal is the seat for meditation.", questions: ["Where in my practice is steadiness without comfort, or comfort without steadiness?", "What would 'relaxing effort' in my posture look like?", "Is my asana practice preparing me to sit still?"], references: ["Yoga Sutras 2.46-2.48", "Yoga Sutras 2.49-2.53"], excerpt: "sthira-sukham āsanam — Posture is steady and comfortable.", evidence: "traditional", dimensions: ["body", "thought"], paths: ["hatha", "raja"], domains: ["health", "learning"], tags: ["yoga_sutras", "asana", "sthira", "sukha", "steady", "comfortable"], difficulty: "beginner", minutes: 5 },
  { concept: "Pranayama — The Cessation of Breath Movement", tradition: "Yoga Sutras", source: "Yoga Sutras 2.49-2.53", explanation: "Patanjali defines pranayama as the cessation of the movement of inhalation and exhalation — not as forceful breathing but as the stilling of breath's motion, with its three movements (external, internal, still) regulated by place, time, and number. Then the covering of the light is destroyed and the mind becomes fit for concentration.", application: "The sutras reframe breathwork: the goal is not bigger breaths but the stilling of breath's movement — including the still fourth phase. Every pranayama practice in this library serves that end.", questions: ["Am I practicing breath control or breath stilling?", "Where is the still phase in my breathing?", "What does 'the covering of the light is destroyed' mean experientially?"], references: ["Yoga Sutras 2.49-2.53", "Yoga Sutras 2.54-2.55"], excerpt: "tasmiṁ sati śvāsa-praśvāsayor gati-vicchedaḥ prāṇāyāmaḥ — The cessation of the movement of inhalation and exhalation.", evidence: "traditional", dimensions: ["body", "thought", "spirit"], paths: ["kriya", "raja"], domains: ["health", "learning"], tags: ["yoga_sutras", "pranayama", "breath", "cessation", "stillness"], difficulty: "intermediate", minutes: 8 },
  { concept: "Pratyahara — The Senses Withdraw", tradition: "Yoga Sutras", source: "Yoga Sutras 2.54-2.55", explanation: "Pratyahara: the senses withdraw from their objects and take on the mind's own form. Patanjali calls it the fifth limb — the hinge between the outer and inner practices. When the senses no longer drag attention outward, the inner limbs become possible.", application: "Pratyahara is the most neglected limb. Practice it directly: in any room, let the senses report without following. The sound is heard; the hearing is not dragged. The door between outer and inner opens.", questions: ["Where do my senses drag me most — sound, sight, taste?", "What would 'the senses take on the mind's form' look like today?", "How is pratyahara different from suppression?"], references: ["Yoga Sutras 2.54-2.55", "Yoga Sutras 3.1-3.3"], excerpt: "sva-viṣayāsamprayoge citasya svarūpānukāra ivendriyāṇāṁ pratyāhāraḥ — The senses withdraw, taking on the mind's form.", evidence: "traditional", dimensions: ["thought", "body", "spirit"], paths: ["raja"], domains: ["learning", "spirituality"], tags: ["yoga_sutras", "pratyahara", "senses", "withdrawal", "fifth_limb"], difficulty: "intermediate", minutes: 7 },
  { concept: "Dharana — Binding Attention to a Place", tradition: "Yoga Sutras", source: "Yoga Sutras 3.1", explanation: "Desha bandhash chittasya dharana — dharana is the binding of attention to a place or object. The sixth limb. Patanjali's definition is precise: concentration is not effort but binding — attention tied to one place, repeatedly returned.", application: "Every focus practice in this library is dharana training. The sutra's gift: when attention wanders, the return is not failure but the practice itself — the binding, renewed.", questions: ["What is my 'place' — my chosen object of binding?", "How many returns did I make today?", "What does the word 'binding' teach about concentration?"], references: ["Yoga Sutras 3.1", "Yoga Sutras 3.2-3.3"], excerpt: "deśa-bandhaś cittasya dhāraṇā — The binding of attention to a place.", evidence: "traditional", dimensions: ["thought"], paths: ["raja"], domains: ["learning"], tags: ["yoga_sutras", "dharana", "concentration", "binding", "sixth_limb"], difficulty: "beginner", minutes: 5 },
  { concept: "Dhyana — The Unbroken Flow", tradition: "Yoga Sutras", source: "Yoga Sutras 3.2", explanation: "Tatra pratyayaika-tanata dhyanam — dhyana is the unbroken flow of attention toward one object. The seventh limb. The difference from dharana: concentration is the repeated binding; meditation is the flow that results. Patanjali distinguishes them by continuity, not intensity.", application: "The sutra removes the mystery from meditation: it is dharana that stopped starting and stopping. You cannot force dhyana; you can only perfect dharana and let the flow arise.", questions: ["Where in my practice is the flow unbroken?", "What breaks the flow most often?", "Can I distinguish the effort of dharana from the ease of dhyana?"], references: ["Yoga Sutras 3.2", "Yoga Sutras 3.3", "Yoga Sutras 3.4"], excerpt: "tatra pratyaya-eka-tanataṁ dhyānam — The unbroken flow of attention there.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["raja"], domains: ["learning", "spirituality"], tags: ["yoga_sutras", "dhyana", "meditation", "flow", "unbroken"], difficulty: "intermediate", minutes: 6 },
  { concept: "Samadhi — Only the Object Shines", tradition: "Yoga Sutras", source: "Yoga Sutras 3.3", explanation: "Tad eva artha-matra nirbhasam svarupa-shunyam iva samadhih — when only the object shines forth and the self's form is absent, that is samadhi. The eighth limb. The definition is radical: absorption is the absence of the meditator's form, not the presence of an experience.", application: "Samadhi is not a state to achieve but an absence to recognize — the absence of the separate meditator. The practice is not to chase absorption but to notice, in dhyana's flow, the moments when the meditator's form is briefly absent.", questions: ["Have I ever noticed the meditator's form absent?", "What is the difference between an experience of absorption and the absence of the experiencer?", "Can samadhi be practiced, or only prepared for?"], references: ["Yoga Sutras 3.3", "Yoga Sutras 3.4-3.8", "Yoga Sutras 1.50-1.51"], excerpt: "tad eva artha-mātra-nirbhasaṁ svarūpa-śūnyam iva samādhiḥ — Only the object shines; the self's form is absent.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["raja"], domains: ["spirituality"], tags: ["yoga_sutras", "samadhi", "absorption", "object", "absence"], difficulty: "advanced", minutes: 9 },
  { concept: "Samyama — The Three Together", tradition: "Yoga Sutras", source: "Yoga Sutras 3.4-3.6", explanation: "Trayam ekatra samyamah — dharana, dhyana, and samadhi practiced together on one object constitute samyama. Patanjali presents the inner three limbs as one continuous act, and samyama as the instrument of the highest knowledge and powers.", application: "Samyama is the library's deepest practice structure: bind attention (dharana), let it flow (dhyana), rest in absorption (samadhi) — on one object. The three are one gesture, not three techniques.", questions: ["Can I feel the transition from binding to flowing to absorbing?", "What object would I choose for samyama?", "What is the relationship between samyama and the powers (siddhis) the sutras describe?"], references: ["Yoga Sutras 3.4-3.6", "Yoga Sutras 3.16-3.56"], excerpt: "trayam ekatra saṁyamaḥ — The three together constitute samyama.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["raja"], domains: ["spirituality", "learning"], tags: ["yoga_sutras", "samyama", "dharana", "dhyana", "samadhi"], difficulty: "advanced", minutes: 8 },
  { concept: "Vitarka Badhane Pratipaksha Bhavanam", tradition: "Yoga Sutras", source: "Yoga Sutras 2.33", explanation: "When disturbed by contrary thoughts, cultivate the opposite. Patanjali's pragmatic instruction — the cognitive antidote centuries before cognitive therapy. The mind is not argued with; it is re-cultivated.", application: "The sutra is the library's oldest cognitive technique. When a toxic thought takes root, do not debate it — cultivate its opposite deliberately. The cultivation, not the argument, is the mechanism.", questions: ["What contrary thought is disturbing me now?", "What is its exact opposite — and can I cultivate it for one minute?", "Why does cultivation work better than argument?"], references: ["Yoga Sutras 2.33", "Yoga Sutras 2.34-2.35"], excerpt: "vitarka-bādhanepratipakṣa-bhāvanam — Cultivate the opposite.", evidence: "traditional", dimensions: ["thought", "emotion"], paths: ["raja", "jnana"], domains: ["growth", "health"], tags: ["yoga_sutras", "pratipaksha", "opposite", "cultivation", "cognitive"], difficulty: "beginner", minutes: 5 },
  { concept: "Non-Violence Ends Enmity", tradition: "Yoga Sutras", source: "Yoga Sutras 2.35", explanation: "Ahimsa-pratishthayam tat-sannidhau vaira-tyagah — when non-violence is established, enmity ceases in one's presence. Patanjali's promise is not that others stop being hostile but that hostility dies in the presence of the established non-violent one.", application: "The sutra reframes ahimsa from moral rule to causal law. The practice: establish ahimsa in thought, word, and deed, and observe what happens to the conflicts around you — not by managing them but by their ceasing in your presence.", questions: ["Where is my ahimsa not established — in thought, word, or deed?", "What enmity surrounds me, and what is my contribution to it?", "What would 'established' non-violence look like this week?"], references: ["Yoga Sutras 2.35", "Yoga Sutras 2.30-2.31"], excerpt: "ahiṁsā-pratiṣṭhāyāṁ tat-sannidhau vaira-tyāgaḥ — When ahimsa is established, enmity ceases.", evidence: "traditional", dimensions: ["action", "connection", "thought"], paths: ["raja", "karma"], domains: ["relationships", "growth"], tags: ["yoga_sutras", "ahimsa", "non_violence", "enmity", "presence"], difficulty: "intermediate", minutes: 7 },
  { concept: "Truthfulness Makes Actions Bear Fruit", tradition: "Yoga Sutras", source: "Yoga Sutras 2.36", explanation: "Satya-pratishthayam kriya-phalasrayatvam — when truthfulness is established, actions bear fruit. The sutra links the second yama to efficacy: the truthful one's actions become reliable causes. Integrity is not moral decoration; it is operational.", application: "Test the sutra in work: where has untruthfulness (exaggeration, omission, false promise) made actions barren? Where has truthfulness made them fruitful? The pattern, once seen, is persuasive.", questions: ["Where is my speech not true — in exaggeration, omission, or promise?", "What action's fruitlessness traces to untruthfulness?", "What would established satya change in my next project?"], references: ["Yoga Sutras 2.36", "Yoga Sutras 2.30-2.31"], excerpt: "satya-pratiṣṭhāyāṁ kriyā-phalāśrayatvam — When truthfulness is established, actions bear fruit.", evidence: "traditional", dimensions: ["action", "thought"], paths: ["raja", "karma"], domains: ["work", "growth"], tags: ["yoga_sutras", "satya", "truthfulness", "fruit", "integrity"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Fourth Pranayama", tradition: "Yoga Sutras", source: "Yoga Sutras 2.51", explanation: "Bahya-abhyantara-vishaya aksepi chaturthah — the fourth pranayama transcends the external and internal movements. Beyond the exhale and the inhale lies the fourth: the stillness that is not a held breath but the cessation of breath's motion itself.", application: "The sutra points to the subtle core of all breathwork: not the phases but the stillness between and beyond them. In practice, attend to the pauses — not as gaps but as the fourth movement.", questions: ["Where is the fourth pranayama in my current breathing?", "What is the difference between holding the breath and the cessation of its movement?", "Can I feel the still phase as a movement of its own?"], references: ["Yoga Sutras 2.50-2.51", "Yoga Sutras 2.52-2.53"], excerpt: "bāhya-abhyantara-viṣayākṣepī caturthaḥ — The fourth transcends the external and internal.", evidence: "traditional", dimensions: ["body", "spirit"], paths: ["kriya", "raja"], domains: ["health", "spirituality"], tags: ["yoga_sutras", "pranayama", "fourth", "stillness", "cessation"], difficulty: "advanced", minutes: 7 },
  { concept: "The Covering of Light Is Destroyed", tradition: "Yoga Sutras", source: "Yoga Sutras 2.52", explanation: "Tato kshiyate prakasha-avaranam — then the covering of the light is destroyed. Patanjali's promise for pranayama: not that light is created but that its covering is removed. The light was always there; breath regulation removes the obstruction.", application: "The sutra teaches the library's central epistemology: practice does not produce light; it removes covering. Every practice in this library is a covering-removal — the experiences are side effects, not goals.", questions: ["What is covering the light in me right now?", "Which practice removes which covering?", "What is the difference between producing light and removing covering?"], references: ["Yoga Sutras 2.52", "Yoga Sutras 2.53", "Yoga Sutras 1.36"], excerpt: "tato kṣīyate prakāśāvaraṇam — Then the covering of the light is destroyed.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["raja", "kriya"], domains: ["spirituality"], tags: ["yoga_sutras", "light", "covering", "prakasha", "destruction"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Mind Becomes Fit for Concentration", tradition: "Yoga Sutras", source: "Yoga Sutras 2.53", explanation: "Dharanaishu cha yogyata manasah — and the mind becomes fit for concentration. The sutra states pranayama's purpose: preparation. Breath regulation is not an end but the preparation of the instrument — the mind — for the inner limbs.", application: "The sutra corrects the modern treatment of breathwork as a wellness product. Pranayama's purpose is fitness for dharana. Ask after every breath session: is my mind now fit to bind attention?", questions: ["Am I practicing breathwork as an end or as preparation?", "What is my mind fit for after pranayama?", "How would my practice change if every breath session were judged by concentration-readiness?"], references: ["Yoga Sutras 2.53", "Yoga Sutras 3.1"], excerpt: "dhāraṇāiśu ca yogyatā manasaḥ — And the mind becomes fit for concentration.", evidence: "traditional", dimensions: ["thought", "body"], paths: ["raja", "kriya"], domains: ["learning", "health"], tags: ["yoga_sutras", "fitness", "concentration", "preparation", "mind"], difficulty: "beginner", minutes: 5 },
  { concept: "Powers Arise from Birth, Herbs, Mantras, Austerity, or Samadhi", tradition: "Yoga Sutras", source: "Yoga Sutras 4.1", explanation: "Janma-oushadhi-mantra-tapas-samadhi-jah siddhayah — powers arise from birth, herbs, mantras, austerity, or samadhi. Patanjali's catalog of the sources of siddhis — and his quiet warning that they are distractions on the path (3.37).", application: "The sutra is the library's stance on extraordinary experiences: they arise, they are not the goal, and clinging to them binds the practitioner. Treat every unusual experience as a siddhi — interesting, not important.", questions: ["What extraordinary experiences have I mistaken for progress?", "Which of the five sources am I actually working with?", "How do I hold experiences lightly, as the sutras advise?"], references: ["Yoga Sutras 4.1", "Yoga Sutras 3.37-3.38", "Yoga Sutras 3.33-3.36"], excerpt: "janma-auṣadhi-mantra-tapaḥ-samādhi-jāḥ siddhayaḥ — Powers arise from birth, herbs, mantras, austerity, or samadhi.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["raja", "jnana"], domains: ["spirituality", "learning"], tags: ["yoga_sutras", "siddhis", "powers", "samadhi", "distraction"], difficulty: "advanced", minutes: 8 },
  { concept: "Kaivalya — Aloneness as Freedom", tradition: "Yoga Sutras", source: "Yoga Sutras 4.34", explanation: "Purusha-artha-shunyanam gunanam pratiprasavah kaivalyam svarupa-pratishtha va chiti-shaktir iti — kaivalya: the gunas return to their source, or consciousness rests in its own nature. The final sutra's double definition: liberation as the unravelling of nature, or as awareness established in its own form.", application: "Kaivalya is the library's horizon — not a place but a recognition. The gunas unwind; awareness rests as itself. Every practice in this library is a small pratiprasava — a return of the modes to their source.", questions: ["What would 'the gunas returning to their source' feel like?", "Is my goal a state or a recognition?", "What is awareness's own nature, prior to every practice?"], references: ["Yoga Sutras 4.34", "Yoga Sutras 4.26-4.33"], excerpt: "puruṣārtha-śūnyānāṁ guṇānāṁ pratiprasavaḥ kaivalyaṁ — The gunas return to their source; that is kaivalya.", evidence: "traditional", dimensions: ["spirit"], paths: ["raja", "jnana"], domains: ["spirituality"], tags: ["yoga_sutras", "kaivalya", "aloneness", "freedom", "gunas", "final"], difficulty: "advanced", minutes: 9 },
];
